import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def boxes(ctx):
    x = torch.rand(4, generator=ctx.rng.torch)
    return {'inputs': x, 'target': torch.stack((x[0], x[1], x[0] + 0.5, x[1] + 0.5))}
class BoxPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.base = build('mlp', 'tiny', in_features=4, out_features=4)
    def forward(self, x):
        raw = self.base(x)
        start = raw[..., :2].sigmoid()
        return {'boxes': torch.cat((start, start + torch.nn.functional.softplus(raw[..., 2:])), dim=-1)}
ds = synth.Spec('structured-boxes', generator=boxes, size=24, splits={'train': 0.75, 'val': 0.25}, seed=7, root=root, monitor='none').run()
train = ds.for_recipe('structured-objective', split='train')
val = ds.for_recipe('structured-objective', split='val', like=train)
trainer = Trainer(BoxPredictor(), train, val, recipe='structured-objective', recipe_config={'loss': 'generalized-iou', 'bindings': {'boxes1': {'output': 'boxes'}, 'boxes2': {'batch': 'target'}}}, batch_size=8, max_epochs=1, device='cpu')
trainer.fit()
assert all(torch.isfinite(torch.tensor(v)) for v in trainer.evaluate(val).values())
